                    <img
                        src={`${assetBase}/images/${filename}`}
                        alt={title}
                        className={`block dark:hidden w-full ${imageHeight} object-cover${imageTop ? ' object-top' : ''} pointer-events-none${fullWidthImage ? '' : ' rounded-lg border border-[#d1d5db]'}`}
                    />
                    <img
                        src={`${assetBase}/images/${darkFilename}`}
                        alt={title}
                        className={`hidden dark:block w-full ${imageHeight} object-cover${imageTop ? ' object-top' : ''} pointer-events-none${fullWidthImage ? '' : ' rounded-lg'}`}
                    />
                    {overlayImg && (
                        <img
                            src={`${assetBase}/images/${overlayImg}`}
