export const AskAILink = ({ children }) => {
    const openKapa = () => {
        if (window.Kapa && typeof window.Kapa.open === 'function') {
            window.Kapa.open({ mode: 'ai' });
            return;
        }
        let attempts = 0;
        const iv = setInterval(() => {
            attempts++;
            if (window.Kapa && typeof window.Kapa.open === 'function') {
                clearInterval(iv);
                window.Kapa.open({ mode: 'ai' });
            } else if (attempts > 60) {
                clearInterval(iv);
            }
        }, 50);
    };
    return (
        <button
            type="button"
            id="home-assistant-entry"
